    function applyI18n(){document.title=tr('title');document.documentElement.lang=currentLang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=tr(el.dataset.i18n));document.getElementById('authStageHint').textContent=tr('checking');document.getElementById('loginOutput').textContent=tr('loginReady');document.getElementById('output').textContent=tr('outputReady');document.getElementById('setupUsername').placeholder=tr('usernamePlaceholder');document.getElementById('loginUsername').placeholder=tr('usernamePlaceholder');document.getElementById('setupEmail').placeholder=tr('adminEmailPlaceholder');document.getElementById('setupPassword').placeholder=tr('adminPassword');document.getElementById('loginPassword').placeholder=tr('adminPassword');document.getElementById('blockedEmail').placeholder=tr('blockedEmailPlaceholder');document.getElementById('blockedIP').placeholder=tr('blockedIpPlaceholder');document.getElementById('blockedEmailReason').placeholder=tr('reason');document.getElementById('blockedIPReason').placeholder=tr('reason');document.getElementById('serverPublicBaseURL').placeholder=tr('centerUrlPlaceholder');document.getElementById('mailHost').placeholder=tr('smtpHostPlaceholder');document.getElementById('mailUsername').placeholder=tr('accountEmailPlaceholder');document.getElementById('mailFromName').placeholder=tr('fromNamePlaceholder');document.getElementById('mailFromEmail').placeholder=tr('accountEmailPlaceholder');document.getElementById('testMailEmail').placeholder=tr('testRecipientPlaceholder');document.getElementById('adminEmailInput').placeholder=tr('adminEmailPlaceholder');if(document.getElementById('routeQueryInput'))document.getElementById('routeQueryInput').placeholder=tr('routeQueryPlaceholder');if(document.getElementById('failureLogsKeyword'))document.getElementById('failureLogsKeyword').placeholder=tr('failureLogsSearchPlaceholder');if(document.getElementById('haNodeID'))document.getElementById('haNodeID').placeholder=tr('haNodeIDPlaceholder');if(document.getElementById('haNodeName'))document.getElementById('haNodeName').placeholder=tr('haNodeNamePlaceholder');if(document.getElementById('haAdvertiseURL'))document.getElementById('haAdvertiseURL').placeholder=tr('haAdvertiseURLPlaceholder');if(document.getElementById('failureLogsPrevButton'))document.getElementById('failureLogsPrevButton').textContent=tr('failureLogsPrev');if(document.getElementById('failureLogsNextButton'))document.getElementById('failureLogsNextButton').textContent=tr('failureLogsNext');document.getElementById('passwordCardTitle').textContent=ptr('title');document.getElementById('passwordCardDesc').textContent=ptr('desc');document.getElementById('currentPasswordLabel').textContent=ptr('current');document.getElementById('newPasswordLabel').textContent=ptr('next');document.getElementById('confirmPasswordLabel').textContent=ptr('confirm');document.getElementById('currentPasswordInput').placeholder=ptr('current');document.getElementById('newPasswordInput').placeholder=ptr('next');document.getElementById('confirmPasswordInput').placeholder=ptr('confirm');document.getElementById('changePasswordButton').textContent=ptr('action');document.querySelectorAll('.lang-switch button').forEach(btn=>{const active=btn.dataset.lang===currentLang;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',active?'true':'false')});}
    function enhanceFormAccessibility(root=document){root.querySelectorAll('label:not([for])').forEach(label=>{if(label.getAttribute('aria-hidden')==='true')return;const control=label.parentElement&&label.parentElement.querySelector('input[id],select[id],textarea[id]');if(control)label.setAttribute('for',control.id)});root.querySelectorAll('input,select,textarea').forEach(control=>{if(control.getAttribute('aria-label')||control.getAttribute('aria-labelledby'))return;const id=control.id||'';if(id&&document.querySelector('label[for="'+CSS.escape(id)+'"]'))return;const label=control.closest('div')&&control.closest('div').querySelector('label');const text=(label&&label.textContent.trim())||control.placeholder||id;if(text)control.setAttribute('aria-label',text)})}
    function enhanceButtonTypes(root=document){root.querySelectorAll('button:not([type])').forEach(button=>{button.type='button'})}
    function enhanceStatusHints(root=document){['haConfigReadinessHint','haRuntimeConfigHint','haClusterSecretHint'].forEach(id=>{const el=root.getElementById?root.getElementById(id):root.querySelector('#'+CSS.escape(id));if(el){el.setAttribute('role','status');el.setAttribute('aria-live','polite')}})}
    function installOverlayDismiss(overlay,closeFn){let startedOnOverlay=false;overlay.addEventListener('pointerdown',e=>{startedOnOverlay=e.target===overlay});overlay.addEventListener('click',e=>{if(startedOnOverlay&&e.target===overlay)closeFn();startedOnOverlay=false})}
    const formA11yObserver=new MutationObserver(mutations=>mutations.forEach(m=>m.addedNodes.forEach(node=>{if(node&&node.nodeType===1){enhanceFormAccessibility(node);enhanceButtonTypes(node)}})));
    formA11yObserver.observe(document.body,{childList:true,subtree:true});
    function setLanguage(lang){currentLang=lang==='zh'?'zh':'en';window.currentLang=currentLang;localStorage.setItem(langKey,currentLang);applyI18n();enhanceFormAccessibility();enhanceButtonTypes();enhanceStatusHints();restoreTab();if(window._lastHubItems)renderHubs(window._lastHubItems);if(lastRouteQueryMeta&&lastRouteQueryData)renderRouteQueryResult(lastRouteQueryMeta,lastRouteQueryData);else if(typeof applyRouteQueryI18n==='function')applyRouteQueryI18n();if(window._enterpriseMailDomainLoaded)renderEnterpriseMailDomains(window._enterpriseMailDomainItems||[]);if(typeof applyInvCodeQueryI18n==='function')applyInvCodeQueryI18n();refreshAdminHeader();}
    function token(){return localStorage.getItem(adminTokenKey)||sessionStorage.getItem(adminTokenKey)||''} function adminProfile(){try{return JSON.parse(localStorage.getItem(adminProfileKey)||sessionStorage.getItem(adminProfileKey)||'null')}catch(_){return null}}
    function setOutput(message,target='output'){const stamp=new Date().toLocaleTimeString();const el=document.getElementById(target);el.textContent='['+stamp+'] '+message+'\n'+el.textContent}
    function showToast(message,type='info'){const root=document.getElementById('toastStack');const toast=document.createElement('div');toast.className='toast '+(type||'info');toast.setAttribute('role',type==='error'?'alert':'status');toast.textContent=message;root.appendChild(toast);requestAnimationFrame(()=>toast.classList.add('show'));const cleanup=()=>{toast.classList.remove('show');setTimeout(()=>toast.remove(),180)};setTimeout(cleanup,3200);toast.addEventListener('click',cleanup,{once:true})}
    function clearConsole(){document.getElementById('output').textContent=tr('outputReady')}
    async function api(path,options={}){const opts={...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};if(token())opts.headers.Authorization='Bearer '+token();let res;try{res=await fetch(path,opts)}catch(_){throw new Error(tr('networkUnavailable'))}let data={},raw='';try{raw=await res.text();data=raw?JSON.parse(raw):{}}catch(_){data={}}if(!res.ok){const code=data.code||(data.error&&data.error.code)||'';const message=data.message||(data.error&&data.error.message)||raw||res.statusText||tr('requestFailed');if(res.status===401&&code==='ADMIN_UNAUTHORIZED'){sessionStorage.removeItem(adminTokenKey);sessionStorage.removeItem(adminProfileKey);localStorage.removeItem(adminTokenKey);localStorage.removeItem(adminProfileKey);showApp(false);const msg=tr('sessionExpired');document.getElementById('loginOutput').textContent=msg;showToast(msg,'error');throw new Error(msg)}const err=new Error(code?message+' ('+code+')':message);err.status=res.status;err.code=code;err.responseBody=raw;throw err}return data}
    function isAdminHubActionRouteMiss(err){return err&&(err.status===404||err.status===405)}
    function hubAdminLegacyPath(id,suffix=''){return '/api/admin/hubs/'+encodeURIComponent(String(id||''))+suffix}
    async function apiHubAdminAction(bodyPath,id,options,legacySuffix){try{return await api(bodyPath,options)}catch(err){if(!isAdminHubActionRouteMiss(err))throw err;try{return await api(hubAdminLegacyPath(id,legacySuffix),options)}catch(fallbackErr){if(isAdminHubActionRouteMiss(fallbackErr))throw err;throw fallbackErr}}}
    async function apiDeleteHubAdminAction(id,options){try{return await api('/api/admin/hubs',options)}catch(err){if(!isAdminHubActionRouteMiss(err))throw err;try{return await api(hubAdminLegacyPath(id),{method:'DELETE'})}catch(fallbackErr){if(isAdminHubActionRouteMiss(fallbackErr))throw err;throw fallbackErr}}}
    async function loadAdminStatus(){return api('/api/admin/status')}
    function showAuthStage(stage){const setup=stage==='setup';document.getElementById('setupStage').classList.toggle('hidden',!setup);document.getElementById('loginStage').classList.toggle('hidden',setup);const setupBtn=document.getElementById('setupStageButton');const loginBtn=document.getElementById('loginStageButton');setupBtn.className=setup?'btn-secondary':'btn-ghost';loginBtn.className=setup?'btn-ghost':'btn-secondary';setupBtn.setAttribute('aria-selected',setup?'true':'false');loginBtn.setAttribute('aria-selected',setup?'false':'true');setupBtn.setAttribute('aria-pressed',setup?'true':'false');loginBtn.setAttribute('aria-pressed',setup?'false':'true');setupBtn.tabIndex=setup?0:-1;loginBtn.tabIndex=setup?-1:0}
    function enhanceAuthStageTabs(){document.querySelectorAll('#stageToggle [role="tab"]').forEach(btn=>btn.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const stage=(event.key==='ArrowLeft'||event.key==='Home')?'setup':'login';showAuthStage(stage);document.getElementById(stage+'StageButton').focus()}))}
    function setSetupAvailability(enabled){document.getElementById('stageToggle').classList.toggle('hidden',!enabled);document.getElementById('setupStageButton').classList.toggle('hidden',!enabled);if(!enabled){document.getElementById('setupStage').classList.add('hidden');document.getElementById('loginStage').classList.remove('hidden');document.getElementById('loginStageButton').className='btn-secondary'}}
    async function refreshAuthStage(){try{const data=await loadAdminStatus();const initialized=!!data.initialized;adminInitialized=initialized;setSetupAvailability(!initialized);document.getElementById('authStageHint').textContent=initialized?tr('canLogin'):tr('needsSetup');showAuthStage(initialized?'login':'setup');return initialized}catch(err){adminInitialized=true;setSetupAvailability(false);setOutput(tr('loadAdminFailed',{error:err.message}),'loginOutput');showAuthStage('login');return true}}
    function refreshAdminHeader(){const profile=adminProfile();document.getElementById('adminDisplayName').textContent=profile?.username||tr('administrator');document.getElementById('adminDisplayMeta').textContent=profile?.email||tr('signedIn');const on=!!token();document.getElementById('authBadge').textContent=on?tr('loggedIn'):tr('loggedOut');document.getElementById('authBadge').className='badge '+(on?'ok':'warn')}
    function showApp(on){document.getElementById('loginView').classList.toggle('hidden',on);document.getElementById('appView').classList.toggle('hidden',!on);refreshAdminHeader();if(!on)refreshAuthStage()}
    function openTab(name){const requested=name;const panel=document.getElementById('tab-'+name);if(!panel){if(requested==='usermgmt'||requested==='userrankings')return;name='overview'}localStorage.setItem(activeTabKey,name);document.querySelectorAll('.nav button').forEach(v=>{const active=v.dataset.tab===name;v.classList.toggle('active',active);if(active)v.setAttribute('aria-current','page');else v.removeAttribute('aria-current')});document.querySelectorAll('.panel').forEach(v=>v.classList.remove('active'));document.getElementById('tab-'+name).classList.add('active');const meta=tabMeta[name]||tabMeta.overview;renderPageTabIcon(name);document.getElementById('pageTitle').textContent=tr(meta[0]);document.getElementById('pageSubtitle').textContent=tr(meta[1]);if(name==='overview'&&typeof loadRoutingDiagnostics==='function')loadRoutingDiagnostics();if(name==='routequery'){if(typeof applyRouteQueryI18n==='function')applyRouteQueryI18n();if(typeof loadEnterpriseMailDomains==='function')loadEnterpriseMailDomains()}if(name==='hubs'&&typeof listHubs==='function')listHubs();if(name==='policies'){if(typeof listBlockedEmails==='function')listBlockedEmails();if(typeof listBlockedIPs==='function')listBlockedIPs()}if(name==='system'){if(typeof loadServerConfig==='function')loadServerConfig();if(typeof loadMailConfig==='function')loadMailConfig()}if(name==='ha'){if(typeof loadHAStatus==='function')loadHAStatus();if(typeof loadHAConfig==='function')loadHAConfig()}if(name==='failurelogs'&&typeof loadFailureLogs==='function')loadFailureLogs();if(name==='gossip'&&typeof loadGossipList==='function')loadGossipList();if(name==='skillhub'){if(typeof reloadCurrentCatalogSubTab==='function')reloadCurrentCatalogSubTab();if((typeof catalogActiveSubTab==='undefined'||catalogActiveSubTab==='skill')&&typeof applyImportI18n==='function')applyImportI18n()}if(name==='skillmarket'){if(typeof loadSkillmarketReview==='function')loadSkillmarketReview();if(typeof loadSmPurchases==='function')loadSmPurchases();if(typeof loadSmTrialConfig==='function')loadSmTrialConfig();if(typeof loadSmUploadAuthConfig==='function')loadSmUploadAuthConfig()}if(name==='computemarket'&&typeof initComputeMarketTab==='function')initComputeMarketTab();if(name==='llmservice'&&typeof initLLMServiceTab==='function')initLLMServiceTab();if(name==='userrankings'&&typeof initUserRankingsTab==='function')initUserRankingsTab();if(name==='news'&&typeof loadNewsList==='function')loadNewsList()}
    function restoreTab(){openTab(localStorage.getItem(activeTabKey)||'overview')}
    function hubRuntimeStatusText(status){const clean=String(status||'').toLowerCase();const map={ready:'hubRuntimeReady',downloading:'hubRuntimeDownloading',partial:'hubRuntimePartial',missing:'hubRuntimeMissing',unavailable:'hubRuntimeUnavailable'};return tr(map[clean]||'hubRuntimeUnavailable')}
    function hubRuntimeBadge(status){const clean=String(status||'').toLowerCase();const map={ready:['ok',tr('hubRuntimeReady')],downloading:['info',tr('hubRuntimeDownloading')],partial:['warn',tr('hubRuntimePartial')],missing:['danger',tr('hubRuntimeMissing')]};const pair=map[clean]||['warn',tr('hubRuntimeUnavailable')];return `<span class="badge ${pair[0]}">${pair[1]}</span>`}
    function hubStatusClass(status,isDisabled=false){if(isDisabled||String(status||'').toLowerCase()==='disabled')return 'danger';return String(status||'').toLowerCase()==='online'?'ok':'warn'}
    function hubStatusText(status,isDisabled=false){if(isDisabled)return tr('statusDisabled');const clean=String(status||'').toLowerCase();const map={online:'statusOnline',offline:'statusOffline',disabled:'statusDisabled',pending_confirmation:'statusPendingConfirmation',pending:'statusPendingConfirmation'};return tr(map[clean]||'statusUnknown')}
    function hubVisibilityText(value){const clean=String(value||'private').toLowerCase();return clean==='shared'?tr('visibilityShared'):tr('visibilityPrivate')}
    function hubEnrollmentText(value){const clean=String(value||'').toLowerCase();const map={open:'enrollmentPublicSignup',approval:'enrollmentInviteOnly',manual:'enrollmentRestricted',public_signup:'enrollmentPublicSignup',public:'enrollmentPublicSignup',invite_only:'enrollmentInviteOnly',restricted:'enrollmentRestricted',domain_restricted:'enrollmentDomainRestricted'};return tr(map[clean]||'enrollmentUnknown')}
    function haStatusText(status){const clean=String(status||'').toLowerCase();const map={healthy:'haOverviewHealthy',online:'online',ready:'hubRuntimeReady',degraded:'haOverviewDegraded',syncing:'haSync',synced:'haStateHealthy',pending:'haStatePending',error:'haError',disabled:'disabled',standalone:'haStandalone'};return map[clean]?tr(map[clean]):(status||'-')}
    function hubRuntimeSummaryStatus(runtime){if(!runtime||!runtime.fetch_ok)return 'problem';const clean=String(runtime.status||'').toLowerCase();if(clean==='ready')return 'ready';if(clean==='downloading')return 'downloading';return 'problem'}
    function hubServicePriority(hub,runtime){const disabled=!!hub?.is_disabled;const online=hub?.status==='online';const shared=String(hub?.visibility||'private').toLowerCase()==='shared';const runtimeState=hubRuntimeSummaryStatus(runtime);if(disabled)return 90;if(online&&shared&&runtimeState==='ready')return 0;if(online&&runtimeState==='ready')return 1;if(online&&shared&&runtimeState==='downloading')return 2;if(online&&runtimeState==='downloading')return 3;if(online&&shared)return 4;if(online)return 5;if(hub?.status==='pending_confirmation')return 6;return 7}
    function rankedHubEntries(items){return (items||[]).map(h=>({hub:h,runtime:hubRuntimeCache[h.id]||null,score:hubServicePriority(h,hubRuntimeCache[h.id]||null)})).sort((a,b)=>a.score-b.score||String(a.hub.name||a.hub.id||'').localeCompare(String(b.hub.name||b.hub.id||'')))}
    function effectiveHubTenantSignupScope(policy,tenantPolicy){let scope=String(tenantPolicy&&tenantPolicy.signup_scope||'').toLowerCase();if(!scope||scope==='inherit')scope=String(policy&&policy.default_signup_scope||'domain_restricted').toLowerCase();return scope||'domain_restricted'}
    function isHubPublicFallback(h){const policy=hubRegistrationPolicy(h);if(String(policy.hub_origin||'').toLowerCase()!=='official')return false;return Object.keys(policy.tenants||{}).some(k=>{const tenant=policy.tenants[k]||{};return !!tenant.is_public_fallback&&String(tenant.status||'active').toLowerCase()!=='disabled'&&effectiveHubTenantSignupScope(policy,tenant)==='public'})}
    function pickPreferredHub(items){return (items||[]).find(h=>isHubPublicFallback(h))||null}
    function hubRouteReason(entry){if(!entry)return tr('hubRouteNoCandidate');if(entry.score<=1)return tr('hubRoutePriorityReady');if(entry.score<=3)return tr('hubRoutePriorityDownloading');if(entry.score<=5)return tr('hubRoutePriorityOnline');if(entry.score===6)return tr('hubRoutePriorityPending');return tr('hubRoutePriorityOffline')}
    function renderHubRuntimeSummary(items){const root=document.getElementById('hubRuntimeSummary');if(!root)return;const counts={ready:0,downloading:0,problem:0};(items||[]).forEach(h=>{counts[hubRuntimeSummaryStatus(hubRuntimeCache[h.id]||null)]++;});const preferred=pickPreferredHub(items);const preferredLabel=preferred?escapeHtml(preferred.name||preferred.id||'-'):tr('na');root.innerHTML=`<div class="item"><div class="item-title">${tr('hubRuntimeSummaryReady')}</div><strong>${counts.ready}</strong><div class="item-meta">${tr('hubRuntimeSummaryReadyDesc')}</div></div><div class="item"><div class="item-title">${tr('hubRuntimeSummaryDownloading')}</div><strong>${counts.downloading}</strong><div class="item-meta">${tr('hubRuntimeSummaryDownloadingDesc')}</div></div><div class="item"><div class="item-title">${tr('hubRuntimePreferred')}</div><strong>${preferredLabel}</strong><div class="item-meta">${tr('hubRuntimePreferredDesc')}</div></div>`}
    function hubMailDomains(hub){const single=String(hub&&hub.corporate_email_domain||'').trim();if(!single)return [];const domains=Array.isArray(hub&&hub.corporate_email_domains)?hub.corporate_email_domains.filter(Boolean):[];if(!domains.includes(single))domains.unshift(single);return domains}
