    function hubRouteCardClass(entry){if(!entry)return 'is-offline';if(entry.score<=1)return 'is-ready';if(entry.score<=3)return 'is-downloading';if(entry.score<=5)return 'is-online';if(entry.score===6)return 'is-pending';return 'is-offline'}
    function ensureHubRouteOverview(){const preview=document.getElementById('hubRoutePreview');const list=document.getElementById('hubRoutePreviewList');if(!preview||!list)return null;let overview=document.getElementById('hubRouteOverview');if(!overview){overview=document.createElement('div');overview.id='hubRouteOverview';overview.className='hub-route-overview';preview.insertBefore(overview,list)}return overview}
    function renderHubRouteOverview(ranked,pageCount){const overview=ensureHubRouteOverview();if(!overview)return;const counts={ready:0,downloading:0,attention:0,offline:0};ranked.forEach(entry=>{if(entry.score<=1)counts.ready++;else if(entry.score<=3)counts.downloading++;else if(entry.score<=6)counts.attention++;else counts.offline++});const serviceFirst=ranked[0]&&ranked[0].score<6?ranked[0].hub:null;overview.innerHTML=`<div class="hub-route-stat"><label>${escapeHtml(tr('hubRuntimeSummaryReady'))}</label><strong>${counts.ready}</strong></div><div class="hub-route-stat"><label>${escapeHtml(tr('hubRuntimeSummaryDownloading'))}</label><strong>${counts.downloading}</strong></div><div class="hub-route-stat"><label>${escapeHtml(tr('hubRuntimeSummaryProblem'))}</label><strong>${counts.attention+counts.offline}</strong></div><div class="hub-route-stat"><label>${escapeHtml(tr('hubRouteRuntimeFirst'))}</label><strong title="${escapeHtml(serviceFirst?serviceFirst.name||serviceFirst.id||'-':tr('na'))}">${escapeHtml(serviceFirst?serviceFirst.name||serviceFirst.id||'-':tr('na'))}</strong></div>`}
    function ensureHubRoutePreviewPager(){const preview=document.getElementById('hubRoutePreview');if(!preview)return null;let pager=document.getElementById('hubRoutePreviewPager');if(!pager){pager=document.createElement('div');pager.id='hubRoutePreviewPager';pager.className='pager pager-compact hub-route-pager';pager.innerHTML='<div id="hubRoutePreviewPageInfo" class="pager-meta" aria-live="polite"></div><div class="pager-actions"><button class="btn-ghost" type="button" onclick="changeHubRoutePage(-1)" aria-label="Previous routing preview page">&larr;</button><button class="btn-ghost" type="button" onclick="changeHubRoutePage(1)" aria-label="Next routing preview page">&rarr;</button></div>';preview.appendChild(pager)}return pager}
    function changeHubRoutePage(delta){hubRoutePreviewPage+=Number(delta)||0;renderHubRoutePreview(window._lastHubItems||[])}
    function renderHubRoutePreview(items){const root=document.getElementById('hubRoutePreviewList');if(!root)return;const pager=ensureHubRoutePreviewPager();const ranked=rankedHubEntries(items);if(!ranked.length){const overview=ensureHubRouteOverview();if(overview)overview.innerHTML='';root.innerHTML='<div class="hint">'+tr('emptyHubs')+'</div>';if(pager)pager.classList.remove('is-visible');return;}const pageCount=Math.max(1,Math.ceil(ranked.length/hubRoutePreviewPageSize));renderHubRouteOverview(ranked,pageCount);hubRoutePreviewPage=Math.min(Math.max(1,hubRoutePreviewPage),pageCount);const start=(hubRoutePreviewPage-1)*hubRoutePreviewPageSize;const pageItems=ranked.slice(start,start+hubRoutePreviewPageSize);root.innerHTML=pageItems.map((entry,idx)=>{const hub=entry.hub||{};const runtime=entry.runtime||null;const statusText=runtime&&runtime.fetch_ok?hubRuntimeStatusText(runtime.status):tr('hubRuntimeUnavailable');return `<div class="hub-route-row ${hubRouteCardClass(entry)}"><div class="hub-route-main"><div class="hub-route-name"><span class="hub-route-order">${start+idx+1}</span><span class="hub-route-name-text" title="${escapeHtml(hub.name||hub.id||'-')}">${escapeHtml(hub.name||hub.id||'-')}</span></div><div class="hub-route-meta"><span class="hub-route-url" title="${escapeHtml(hub.base_url||tr('na'))}">${escapeHtml(hub.base_url||tr('na'))}</span><span class="hub-route-reason">${escapeHtml(hubRouteReason(entry))}</span><span class="hub-route-policy" title="${escapeHtml(hubSignupPolicyText(hub))}">${escapeHtml(hubSignupPolicyText(hub))}</span></div></div><div class="hub-route-side"><div>${hubRuntimeBadge(runtime&&runtime.fetch_ok?runtime.status:'unavailable')}</div><div class="hub-route-meta">${escapeHtml(statusText)}</div></div></div>`}).join('');if(pager){const end=Math.min(start+pageItems.length,ranked.length);pager.classList.toggle('is-visible',ranked.length>hubRoutePreviewPageSize);const info=document.getElementById('hubRoutePreviewPageInfo');if(info)info.textContent=`${start+1}-${end} / ${ranked.length}`;const buttons=pager.querySelectorAll('button');if(buttons[0])buttons[0].disabled=hubRoutePreviewPage<=1;if(buttons[1])buttons[1].disabled=hubRoutePreviewPage>=pageCount}}
    function rankedHubURLs(items){return rankedHubEntries(items).map(entry=>String(entry.hub?.base_url||'').trim()).filter(v=>!!v)}
