    function hubAuthSummary(auth){const quota=Number(auth&&auth.quota||0);const enabled=auth?!!auth.enabled:false;const active=auth?!!auth.active:false;const expires=auth&&auth.expires_at||'';const state=!auth?tr('veStateNotConfigured'):(!enabled?tr('veStateDisabled'):(active?tr('veStateActive'):(quota<=0?tr('veStateNoQuota'):tr('veStateExpired'))));const badgeClass=active?'ok':'warn';let expiresText=tr('veNotSet');if(expires){const d=new Date(expires);expiresText=isNaN(d.getTime())?String(expires):d.toLocaleDateString()}return {quota,enabled,active,expires,state,badgeClass,expiresText}}
