    function hubComputeTenantAliases(tenantID){const raw=String(tenantID||'').trim();const values=[];const add=v=>{v=String(v||'').trim();if(!values.includes(v))values.push(v)};add(raw);if(!raw||raw==='tenant_default'||raw==='default'){add('tenant_default');add('default');add('')}else if(raw.startsWith('tenant_')){add(raw.slice(7))}else{add('tenant_'+raw)}return values}
    function hubComputeAuthsForTenant(hubID,tenantID){const aliases=hubComputeTenantAliases(tenantID);return hubComputeAuthorizations.filter(a=>String(a&&a.hub_id||'')===String(hubID||'')&&aliases.includes(String(a&&a.tenant_id||'').trim())&&!!(a&&a.is_external_compute_access))}
    function hubComputeAuthIsActive(auth){if(!auth||!auth.allow_external_providers)return false;if(String(auth.status||'active')!=='active')return false;const expires=auth.expires_at?new Date(auth.expires_at):null;return !expires||isNaN(expires.getTime())||expires.getTime()>Date.now()}
    function renderHubComputeAuthPanel(h,selected){
      const id=String(h&&h.id||'');
      const selectedKey=hubTenantKey(selected);
      const domID=hubDOMID(id);
      const auths=hubComputeAuthsForTenant(id,selectedKey);
      const allowed=auths.some(hubComputeAuthIsActive);
      let statusHtml='';
      if(hubComputeAuthLoading&&!hubComputeAuthLoaded){
        statusHtml='<div class="hint">'+escapeHtml(tr('hubComputeLoading'))+'</div>';
      }else if(!allowed){
        statusHtml='<div class="hint">'+escapeHtml(tr('hubComputeNoAuths'))+'</div>';
      }
      const disabled=!selectedKey;
      const form='<div class="hub-compute-grant-actions section-gap-sm"><label class="inline-check"><input type="checkbox" id="hubComputeExternal-'+escapeHtml(domID)+'"'+(allowed?' checked':'')+'><span>'+escapeHtml(tr('hubComputeAllowExternal'))+'</span></label><button class="btn-primary" onclick="grantHubComputeAuth('+jsStringArg(id)+','+jsStringArg(selectedKey)+')"'+(disabled?' disabled':'')+'>'+escapeHtml(tr('hubComputeGrant'))+'</button></div>';
      return '<div class="hub-tenant-detail hub-compute-panel section-gap-sm"><div class="item-head"><div><div class="item-title">'+escapeHtml(tr('hubComputeAuthTitle'))+'</div><div class="item-meta">'+escapeHtml(tr('hubComputeAuthDesc'))+'</div></div><span class="badge '+(allowed?'ok':'warn')+'">'+escapeHtml(allowed?tr('hubComputeAllowed'):tr('hubComputeNotAllowed'))+'</span></div>'+statusHtml+form+'</div>';
    }
    async function loadHubComputeAuthData(force=false){if(hubComputeAuthLoading)return;if(hubComputeAuthLoaded&&!force)return;hubComputeAuthLoading=true;if(hubConfigModalHubID&&document.getElementById('hubConfigModalOverlay'))renderHubConfigModalContent();try{const data=await api('/api/admin/llm/authorizations');hubComputeAuthorizations=data.authorizations||[];hubComputeAuthLoaded=true}catch(err){hubComputeAuthorizations=[];showToast(tr('hubComputeLoadFailed',{error:err.message}),'error')}finally{hubComputeAuthLoading=false;if(hubConfigModalHubID&&document.getElementById('hubConfigModalOverlay'))renderHubConfigModalContent()}}
