    function showVEAuthModal(html){var existing=document.getElementById('veAuthModalOverlay');if(existing)existing.remove();veAuthModalReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;var overlay=document.createElement('div');overlay.id='veAuthModalOverlay';overlay.className='ve-auth-overlay';var titleId='veAuthModalTitle';if(html.indexOf('<h3')!==-1&&html.indexOf('id="'+titleId+'"')===-1)html=html.replace('<h3','<h3 id="'+titleId+'"');overlay.innerHTML='<div class="ve-auth-dialog" role="dialog" aria-modal="true" aria-labelledby="'+titleId+'" tabindex="-1">'+html+'</div>';document.body.appendChild(overlay);enhanceFormAccessibility(overlay);var dialog=overlay.querySelector('[role="dialog"]');var focusable='button,input,select,textarea,a[href],[tabindex]:not([tabindex="-1"])';var target=overlay.querySelector(focusable)||dialog;target.focus();installOverlayDismiss(overlay,closeVEAuthModal);overlay.addEventListener('keydown',function(e){if(e.key==='Escape'){e.preventDefault();closeVEAuthModal();return}if(e.key!=='Tab')return;var nodes=[].slice.call(overlay.querySelectorAll(focusable)).filter(function(el){return !el.disabled&&el.offsetParent!==null});if(!nodes.length){e.preventDefault();dialog.focus();return}var first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}})}
