    function computeVEAuthExpiry(startDate,years){var d=new Date(startDate||new Date().toISOString().slice(0,10));if(isNaN(d.getTime()))return '-';d.setFullYear(d.getFullYear()+Number(years||1));return d.toLocaleDateString()}
