    async function updateHubVEAuth(id,currentQuota,tenantID){var hub=null;if(window._lastHubItems){hub=window._lastHubItems.find(function(h){return h.id===id})}tenantID=String(tenantID||'');if(!tenantID){showToast(tr('veAuthSelectTenantManage'),'error');return}var tenant=hubTenantsForAdmin(hub).find(function(t){return hubTenantKey(t)===tenantID});var auth=hubTenantAuth(hub,tenantID);var summary=hubAuthSummary(auth);var quota=Number(currentQuota||summary.quota||0);var expiresAt=summary.expires||'';var startDate=new Date().toISOString().slice(0,10);if(expiresAt){var expiryDate=new Date(expiresAt);if(!isNaN(expiryDate.getTime())&&expiryDate>Date.now()){startDate=expiryDate.toISOString().slice(0,10)}}var durationYears=1;showVEAuthModal('<h3 class="ve-auth-title">'+escapeHtml(tr('veAuthTitle'))+'</h3>'+'<div class="ve-auth-context">'+escapeHtml(tr('veAuthHub'))+': '+(hub?escapeHtml(hub.name||hub.id):escapeHtml(id))+'<br>'+escapeHtml(tr('veAuthTenant'))+': '+escapeHtml(tenant?hubTenantLabel(tenant):tenantID)+'</div>'+'<div class="ve-auth-summary">'+'<div class="ve-auth-row ve-auth-row-head"><span>'+escapeHtml(tr('veAuthCurrentState'))+'</span><span class="badge '+summary.badgeClass+' ve-auth-badge">'+escapeHtml(summary.state)+'</span></div>'+'<div class="ve-auth-row"><span>'+escapeHtml(tr('veAuthCurrentQuota'))+'</span><strong>'+quota+'</strong></div>'+'<div class="ve-auth-row"><span>'+escapeHtml(tr('veAuthExpiresAt'))+'</span><strong>'+escapeHtml(summary.expiresText)+'</strong></div>'+'</div>'+'<div class="ve-auth-fields">'+'<div><label>'+escapeHtml(tr('veAuthQuotaLabel'))+' <span>('+escapeHtml(tr('veAuthIncreaseOnly'))+')</span></label><input id="veAuthQuotaInput" type="number" min="'+Math.max(1,quota)+'" value="'+Math.max(1,quota)+'"></div>'+'<div><label>'+escapeHtml(tr('veAuthStartDate'))+'</label><input id="veAuthStartInput" type="date" value="'+startDate+'" oninput="updateVEAuthExpiryPreview()"></div>'+'<div><label>'+escapeHtml(tr('veAuthDurationYears'))+'</label><input id="veAuthYearsInput" type="number" min="1" max="10" value="'+durationYears+'" oninput="updateVEAuthExpiryPreview()"></div>'+'</div>'+'<div id="veAuthExpiryPreview" class="ve-auth-preview">'+escapeHtml(tr('veAuthExpiryDate',{date:computeVEAuthExpiry(startDate,durationYears)}))+'</div>'+'<div class="ve-auth-actions">'+'<button class="btn-secondary" onclick="closeVEAuthModal()">'+escapeHtml(tr('veAuthCancel'))+'</button>'+'<button class="btn-primary" onclick="submitVEAuthModal('+jsStringArg(id)+','+quota+','+jsStringArg(tenantID)+')">'+escapeHtml(tr('veAuthConfirm'))+'</button>'+'</div>')}
    async function submitVEAuthModal(id,minQuota,tenantID){try{var quotaVal=Number(document.getElementById('veAuthQuotaInput').value);var yearsVal=Number(document.getElementById('veAuthYearsInput').value);var startDateVal=document.getElementById('veAuthStartInput').value||'';tenantID=String(tenantID||'');if(!tenantID){showToast(tr('veAuthTenantRequired'),'error');return}if(!Number.isFinite(quotaVal)||quotaVal<1){showToast(tr('veAuthQuotaRequired'),'error');return}if(quotaVal<minQuota){showToast(tr('veAuthQuotaIncrease',{quota:minQuota}),'error');return}if(!Number.isFinite(yearsVal)||yearsVal<1||yearsVal>10){showToast(tr('veAuthYearsInvalid'),'error');return}if(startDateVal&&isNaN(Date.parse(startDateVal))){showToast(tr('veAuthStartInvalid'),'error');return}var body={hub_id:String(id||''),tenant_id:tenantID,quota:quotaVal,years:yearsVal,enabled:true};if(startDateVal)body.start_date=startDateVal;await apiHubAdminAction('/api/admin/hubs/digital-employee-authorization',id,{method:'POST',body:JSON.stringify(body)},'/digital-employee-authorization');closeVEAuthModal();showToast(tr('veAuthUpdated'),'success');await listHubs()}catch(err){showToast(err.message,'error')}}
